macro_rules! deps {
    () => {
        Slab!();
        Entry!();
    };
}

macro_rules! OwnedEntry {
    () => {
        deps!();
        # [doc = " An owned reference to an occupied entry in a [`Slab`]."] # [doc = ""] # [doc = " While the guard exists, it indicates to the slab that the item the guard"] # [doc = " references is currently being accessed. If the item is removed from the slab"] # [doc = " while the guard exists, the  removal will be deferred until all guards are"] # [doc = " dropped."] # [doc = ""] # [doc = " Unlike [`Entry`], which borrows the slab, an `OwnedEntry` clones the [`Arc`]"] # [doc = " around the slab. Therefore, it keeps the slab from being dropped until all"] # [doc = " such guards have been dropped. This means that an `OwnedEntry` may be held for"] # [doc = " an arbitrary lifetime."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use sharded_slab::Slab;"] # [doc = " use std::sync::Arc;"] # [doc = ""] # [doc = " let slab: Arc<Slab<&'static str>> = Arc::new(Slab::new());"] # [doc = " let key = slab.insert(\"hello world\").unwrap();"] # [doc = ""] # [doc = " // Look up the created key, returning an `OwnedEntry`."] # [doc = " let value = slab.clone().get_owned(key).unwrap();"] # [doc = ""] # [doc = " // Now, the original `Arc` clone of the slab may be dropped, but the"] # [doc = " // returned `OwnedEntry` can still access the value."] # [doc = " assert_eq!(value, \"hello world\");"] # [doc = " ```"] # [doc = ""] # [doc = " Unlike [`Entry`], an `OwnedEntry` may be stored in a struct which must live"] # [doc = " for the `'static` lifetime:"] # [doc = ""] # [doc = " ```"] # [doc = " # use sharded_slab::Slab;"] # [doc = " use sharded_slab::OwnedEntry;"] # [doc = " use std::sync::Arc;"] # [doc = ""] # [doc = " pub struct MyStruct {"] # [doc = "     entry: OwnedEntry<&'static str>,"] # [doc = "     // ... other fields ..."] # [doc = " }"] # [doc = ""] # [doc = " // Suppose this is some arbitrary function which requires a value that"] # [doc = " // lives for the 'static lifetime..."] # [doc = " fn function_requiring_static<T: 'static>(t: &T) {"] # [doc = "     // ... do something extremely important and interesting ..."] # [doc = " }"] # [doc = ""] # [doc = " let slab: Arc<Slab<&'static str>> = Arc::new(Slab::new());"] # [doc = " let key = slab.insert(\"hello world\").unwrap();"] # [doc = ""] # [doc = " // Look up the created key, returning an `OwnedEntry`."] # [doc = " let entry = slab.clone().get_owned(key).unwrap();"] # [doc = " let my_struct = MyStruct {"] # [doc = "     entry,"] # [doc = "     // ..."] # [doc = " };"] # [doc = ""] # [doc = " // We can use `my_struct` anywhere where it is required to have the"] # [doc = " // `'static` lifetime:"] # [doc = " function_requiring_static(&my_struct);"] # [doc = " ```"] # [doc = ""] # [doc = " `OwnedEntry`s may be sent between threads:"] # [doc = ""] # [doc = " ```"] # [doc = " # use sharded_slab::Slab;"] # [doc = " use std::{thread, sync::Arc};"] # [doc = ""] # [doc = " let slab: Arc<Slab<&'static str>> = Arc::new(Slab::new());"] # [doc = " let key = slab.insert(\"hello world\").unwrap();"] # [doc = ""] # [doc = " // Look up the created key, returning an `OwnedEntry`."] # [doc = " let value = slab.clone().get_owned(key).unwrap();"] # [doc = ""] # [doc = " thread::spawn(move || {"] # [doc = "     assert_eq!(value, \"hello world\");"] # [doc = "     // ..."] # [doc = " }).join().unwrap();"] # [doc = " ```"] # [doc = ""] # [doc = " [`get`]: Slab::get"] # [doc = " [`Arc`]: std::sync::Arc"] pub struct OwnedEntry < T , C = DefaultConfig > where C : cfg :: Config , { inner : page :: slot :: Guard < Option < T > , C > , value : ptr :: NonNull < T > , slab : Arc < Slab < T , C > > , key : usize , }
    };
}

OwnedEntry!()